namespace sv_79357fca92fb49f4b93b032a81a853e5.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Interactive Server mode, scoped = one instance per circuit,
/// so each user gets independent state that persists across enhanced navigations.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        NotifyStateChanged();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        NotifyStateChanged();
    }

    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@using sv_79357fca92fb49f4b93b032a81a853e5.Services
@inject ThemeService ThemeService
@implements IDisposable
@rendermode InteractiveServer

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @GetThemeIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@using sv_79357fca92fb49f4b93b032a81a853e5.Services
@inject ThemeService ThemeService
@implements IDisposable
@rendermode InteractiveServer

<div class="theme-toggle">
    <button class="btn btn-sm @GetButtonClass(ThemeMode.Light)" @onclick="() => ThemeService.SetTheme(ThemeMode.Light)">☀️ Light</button>
    <button class="btn btn-sm @GetButtonClass(ThemeMode.Dark)" @onclick="() => ThemeService.SetTheme(ThemeMode.Dark)">🌙 Dark</button>
    <button class="btn btn-sm @GetButtonClass(ThemeMode.System)" @onclick="() => ThemeService.SetTheme(ThemeMode.System)">💻 System</button>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private string GetButtonClass(ThemeMode mode) =>
        ThemeService.Theme == mode ? "btn-primary" : "btn-outline-secondary";

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@using sv_79357fca92fb49f4b93b032a81a853e5.Services
@inject ThemeService ThemeService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>User Preferences</PageTitle>

<h3>User Preferences</h3>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>
        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@ThemeService.Theme" @onchange="OnThemeChanged">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@ThemeService.AccentColor"
                   @onchange="OnAccentColorChanged" />
            <small class="text-muted">Current: @ThemeService.AccentColor</small>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeService.SetTheme(mode);
        }
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString();
        if (!string.IsNullOrEmpty(color))
        {
            ThemeService.SetAccentColor(color);
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

